def contract_errors(msg):
    errors = []
    oid = msg.get('order_id')
    if not isinstance(oid, str) or not oid:
        errors.append('order_id')
    amt = msg.get('amount_cents')
    if not isinstance(amt, int) or isinstance(amt, bool) or amt < 1:
        errors.append('amount_cents')
    if msg.get('currency') not in ('USD', 'EUR', 'GBP'):
        errors.append('currency')
    for key in msg:
        if key not in ('order_id', 'amount_cents', 'currency'):
            errors.append('extra:' + key)
    return sorted(errors)
